    while (lo < hi) {
        int64 mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }

    printf("%lld\n", lo);

    free(x);
    free(coordU);
    free(coordV);
    free(orderU);
    free(orderV);
    free(alive);
    free(color);
    free(queueArr);
    return 0;
}
